	// Jitter provides a range to randomize backoff delays.
	Jitter float64
	baseDelaySet bool
	multiplierSet bool
	jitterSet bool
}

func (bc Exponential) Backoff(retries int) time.Duration {
	base := bc.BaseDelay
	if !bc.baseDelaySet && base == 0 {
		base = baseDelay
	}
	if retries == 0 {
		return base
	}
	mult := bc.Multiplier
	if !bc.multiplierSet && mult == 0 {
		mult = factor
	}
	j := bc.Jitter
	if !bc.jitterSet && j == 0 {
		j = jitter
	}
	backoff, max := float64(base), float64(bc.MaxDelay)
	for backoff < max && retries > 0 {
		backoff *= mult
		retries--
	}
	if backoff > max {
		backoff = max
	}
	// Randomize backoff delays so that if a cluster of requests start at
	// the same time, they won't operate in lockstep.
	backoff *= 1 + j*(grpcrand.Float64()*2-1)
	if backoff < 0 {
		return 0
	}
	return time.Duration(backoff)
}

type exponentialBuilder struct {
	config Exponential
	maxDelaySet bool
}

func NewExponentialBuilder() StrategyBuilder {
	return &exponentialBuilder{}
}

func (b *exponentialBuilder) SetBaseDelay(d time.Duration) StrategyBuilder {
	b.config.BaseDelay = d
	b.config.baseDelaySet = true
	return b
}

func (b *exponentialBuilder) SetMultiplier(m float64) StrategyBuilder {
	b.config.Multiplier = m
	b.config.multiplierSet = true
	return b
}

func (b *exponentialBuilder) SetJitter(j float64) StrategyBuilder {
	b.config.Jitter = j
	b.config.jitterSet = true
	return b
}

func (b *exponentialBuilder) SetMaxDelay(d time.Duration) StrategyBuilder {
	b.config.MaxDelay = d
	b.maxDelaySet = true
	return b
}

func (b *exponentialBuilder) Build() Strategy {
	if !b.maxDelaySet {
		b.config.MaxDelay = 120 * time.Second
	}
	return b.config
}

type ConnectParams struct {
	// BackoffBaseDelay is the initial delay between connection attempts.
	BackoffBaseDelay time.Duration
	// BackoffMultiplier is the factor by which the backoff delay grows.
	BackoffMultiplier float64
	// BackoffJitter controls the randomization applied to backoff delays.
	BackoffJitter float64
	// BackoffMaxDelay is the upper bound of the backoff delay.
	BackoffMaxDelay time.Duration
	// MinConnectTimeout is the minimum time allowed for a connection attempt.
	MinConnectTimeout time.Duration
}

func WithBackoffConfig(b BackoffConfig) DialOption {
	return newFuncDialOption(func(o *dialOptions) {
		builder := backoff.NewExponentialBuilder().SetMaxDelay(b.MaxDelay)
		if b.BaseDelay != 0 {
			builder.SetBaseDelay(b.BaseDelay)
		}
		if b.Multiplier != 0 {
			builder.SetMultiplier(b.Multiplier)
		}
		if b.Jitter != 0 {
			builder.SetJitter(b.Jitter)
		}
		o.bs = builder.Build()
		if b.MinConnectTimeout != 0 {
			timeout := b.MinConnectTimeout
			o.minConnectTimeout = func() time.Duration { return timeout }
		} else {
			o.minConnectTimeout = nil
		}
	})
}

func WithConnectParams(p ConnectParams) DialOption {
	return newFuncDialOption(func(o *dialOptions) {
		o.bs = backoff.NewExponentialBuilder().
			SetBaseDelay(p.BackoffBaseDelay).
			SetMultiplier(p.BackoffMultiplier).
			SetJitter(p.BackoffJitter).
			SetMaxDelay(p.BackoffMaxDelay).
			Build()
		if p.MinConnectTimeout != 0 {
			timeout := p.MinConnectTimeout
			o.minConnectTimeout = func() time.Duration { return timeout }
		} else {
			o.minConnectTimeout = nil
		}
	})
}

